def find_structure_bounding(test_input, wall_color):
    """Find bounding box of all occurrences of wall_color that form structures"""
    heights = []
    widths = []
    for r in range(len(test_input)):
        for c in range(len(test_input[r])):
            if test_input[r][c] == wall_color:
                heights.append(r)
                widths.append(c)
    if not heights:
        return None
    min_r, max_r = min(heights), max(heights)
    min_c, max_c = min(widths), max(widths)
    return (min_r, min_c, max_r, max_c)

